/**
 * One exported glyph, centred in the slot Figma reserved for it.
 *
 * `box` is the slot — square unless `boxH` says otherwise, which only the
 * 343×94 overdraft plate needs. `w`/`h` default to the slot for assets that
 * already fill their frame (the 40×40 illustrations, the 16×16 star). `offset`
 * is for the one glyph Figma does not centre: the overdraft hand sits
 * 1.5/0.83 off-centre in its 16 box.
 *
 * `tint` rewrites the asset's white fills. Most of these glyphs were exported
 * from the dark frame, where every on-surface icon is white; a few of those
 * surfaces are white themselves in light mode, and a white glyph on a white
 * card is simply not there.
 */
export function FigmaIcon({
  xml,
  box,
  boxH,
  w,
  h,
  offset,
  tint,
  style,
}: {
  xml: string;
  box: number;
  boxH?: number;
  w?: number;
  h?: number;
  offset?: { left: number; top: number };
  tint?: string;
  style?: StyleProp<ViewStyle>;
}) {
  const slotH = boxH ?? box;
  const leafW = w ?? box;
  const leafH = h ?? slotH;
  const markup = tint ? xml.replace(/fill="white"/g, `fill="${tint}"`) : xml;

  return (
    <View
      style={[{ width: box, height: slotH }, offset ? undefined : styles.centre, style]}>
      <SvgXml
        xml={markup}
        width={leafW}
        height={leafH}
        style={offset ? { position: 'absolute', left: offset.left, top: offset.top } : undefined}
      />
    </View>
  );
}

/**
 * Savings is two exported layers, not one: a back stack of three coins and a
 * front stack of two, each with its own inset inside the 40×40 slot. Drawing
 * them at one size would lose the overlap the illustration depends on.
 */
export function SavingsIllo({ size = 40 }: { size?: number }) {
  const k = size / 40;
  return (
    <View style={{ width: size, height: size, overflow: 'hidden' }}>
      <SvgXml
        xml={SAVINGS_BACK}
        width={21.075 * k}
        height={27.7328 * k}
        style={{ position: 'absolute', left: 16.026 * k, top: 2.274 * k }}
      />
      <SvgXml
        xml={SAVINGS_FRONT}
        width={21.075 * k}
        height={21.4828 * k}
        style={{ position: 'absolute', left: 1.961 * k, top: 14.774 * k }}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  centre: { alignItems: 'center', justifyContent: 'center' },
});
